import collections

def resolve(path, cwd, links):
    if not path.startswith('/'):
        path = cwd.rstrip('/') + '/' + path
    queue = collections.deque(path.split('/'))
    result = []  # list of path components (no slashes) representing resolved path from root
    link_count = 0

    while queue:
        comp = queue.popleft()
        if comp == '' or comp == '.':
            continue
        elif comp == '..':
            if result:
                result.pop()
        else:
            result.append(comp)
            current = '/' + '/'.join(result)
            if current in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[current]
                if not target.startswith('/'):
                    dir_path = '/' + '/'.join(result[:-1])
                    if dir_path != '/':
                        target = dir_path + '/' + target
                    else:
                        target = '/' + target
                # remove the component we just added, since it's replaced by link target
                result.pop()
                target_components = target.split('/')
                queue.extendleft(reversed(target_components))

    if not result:
        return '/'
    return '/' + '/'.join(result)

